// Requires, in this order, before this file:
//   <script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2"></script>
//   <script src="/env.js"></script>
//
// `window.__ENV__` is generated by the Express server from process.env
// (see server.js -> GET /env.js), so no keys are hardcoded here.

if (!window.__ENV__ || !window.__ENV__.SUPABASE_URL || !window.__ENV__.SUPABASE_ANON_KEY) {
    document.body.innerHTML =
        '<div style="padding:24px;font-family:sans-serif;color:#b00">' +
        'Server config missing. Make sure the app is running via <code>node server.js</code> ' +
        'with a valid .env file (see .env.example).</div>';
    throw new Error('Missing window.__ENV__ — is server.js running with a valid .env?');
}

// Named `sb` (not `supabase`) so we don't clobber the supabase-js library
// namespace that the CDN script attaches to `window.supabase`.
window.sb = window.supabase.createClient(
    window.__ENV__.SUPABASE_URL,
    window.__ENV__.SUPABASE_ANON_KEY
);
